1	import { spawn, ChildProcess } from "node:child_process";
2	import * as path from "node:path";
3	import * as fs from "node:fs";
4	import * as os from "node:os";
5	import { pathToFileURL, fileURLToPath } from "node:url";
6	import { buildMcpEnvironment } from "./mcp.js";
7	import { fenceUntrusted, sanitizeDiagnosticMessage } from "./diagnostics.js";
8	import { redactPlain } from "./protocol.js";
9	
10	const LSP_MAX_BUFFER_BYTES = 16 * 1024 * 1024;
11	const LSP_TOOLCHAIN_VARS = ["RUSTUP_HOME", "CARGO_HOME", "RUSTUP_TOOLCHAIN", "GOPATH", "GOROOT", "GOCACHE", "GOMODCACHE"];
12	/**
13	 * Documents one server keeps open; the least recently queried one beyond this is closed (`didClose`), which hands that
14	 * file back to the server's own reading of the disk. Every query re-checks every open document (one realpath and one
15	 * stat each), and a server re-analyses its open documents on each change, so the set is kept to what an agent works on
16	 * at one time (an editor's worth of tabs), not every file it ever asked about.
17	 */
18	export const MAX_OPEN_DOCUMENTS = 32;
19	/**
20	 * A file's stat is taken as proof that it has not changed only when its newest timestamp was at least this old when the
21	 * file was read. Timestamps come from a clock that advances in steps (a kernel tick, or 1 to 2 s on coarse file systems):
22	 * a second write inside the step of the first leaves them equal, so a file changed that recently is compared by content.
23	 */
24	export const STAT_SETTLE_MS = 2_000;
25	/**
26	 * Push-only servers: how long the server must have published nothing before a list that predates a change to another
27	 * document is taken as still standing (see `settledAt`). It has to outlast the gap between a server's publish for the
28	 * changed file and its publish for a dependent one; servers batch or debounce those within a few hundred milliseconds,
29	 * and 1 s is several times that. Longer would make every such query slower by as much; shorter would return more old
30	 * lists from a server that is slow to reach the dependent file. Counted from the last publish, so a query made a moment
31	 * after an edit usually finds most of it already spent.
32	 */
33	export const PUBLISH_QUIET_MS = 1_000;
34	
35	// ---------------------------------------------------------------------------------------------------------- timings
36	// One value per phase, each tied to what was measured (docs/LSP_REAL_SERVERS.md) or marked as a judgement. A server's
37	// spec can override any of them (`LspServerSpec.timings`), and a manager option overrides both (tests pass small values).
38	
39	/**
40	 * Start: how long `initialize` may take. All four real servers answered inside the former 5 s limit on the hosted runs
41	 * (44606102675, 44670790609); a server that is missing or exits is reported at once and no longer waits for this, so the
42	 * limit only costs when a process hangs. Twice the proven value, for a loaded machine. A judgement, not a measurement.
43	 */
44	export const LSP_START_TIMEOUT_MS = 10_000;
45	/**
46	 * A query on a server that is ready: the value the tools always used. Also how long a call waits, at the least, on a
47	 * server that is not ready, and the timeout of one hover or definition request.
48	 */
49	export const LSP_WARM_QUERY_TIMEOUT_MS = 5_000;
50	/**
51	 * Cold start: how long after `initialize` a call may wait for the server's first analysis, and how long a server that
52	 * reports no progress is taken to be warming up. The default adds nothing to the warm timeout: no first-query time is
53	 * recorded for typescript-language-server, pyright or gopls (the real-server suite passes 60 to 90 s and does not record
54	 * what was used), so nothing longer is justified yet.
55	 */
56	export const LSP_COLD_START_ALLOWANCE_MS = LSP_WARM_QUERY_TIMEOUT_MS;
57	/**
58	 * rust-analyzer: a first diagnostics call on a tiny crate took about 13 s locally and about 18 s on a hosted runner;
59	 * 25 s covers the slower one with 40% to spare.
60	 *
61	 * THE COLD-START DECISION: a bounded longer first wait, not "unavailable, try again" after the warm timeout. With the
62	 * measured 13 to 18 s, the warm timeout would end three or four calls in a row as "still indexing", each a model round
63	 * trip that costs more than the seconds it saves, where one call that waits returns the real answer. The wait is bounded
64	 * and is counted from the server's start, not from the call: a call made while the server is still indexing waits for
65	 * what is left of the allowance (at least the warm timeout), so a second call never starts the allowance over, and one
66	 * made after it has run out reports the state, with the time indexing has taken, after the warm timeout. A project that
67	 * needs longer keeps indexing between calls; `LspBridgeManager.warmUp` starts that before the first query.
68	 */
69	export const RUST_ANALYZER_COLD_START_ALLOWANCE_MS = 25_000;
70	/** A server's progress must have been over for this long before it counts as ready and its lists as final (rust-analyzer runs its phases back to back; passed on the real server since CS-6). */
71	export const LSP_PROGRESS_QUIET_MS = 1_500;
72	/**
73	 * Staged servers, after an edit: when no progress cycle begins after the change (no check on save), a list for the new
74	 * version is taken as final this long after the change. 8 s is the window the real rust-analyzer case needed: it
75	 * reproduced a version-matched list that still carried the previous `rustc` result right after an edit. A cycle that
76	 * began after the change and ended is the usual evidence, and does not wait for this.
77	 */
78	export const LSP_EDIT_SETTLE_MS = 8_000;
79	/** Hover and definition on a server that is not ready: the first pause before asking again; it doubles up to the cap. A judgement. */
80	export const LSP_READINESS_RETRY_MS = 250;
81	const READINESS_RETRY_CAP_MS = 2_000;
82	/**
83	 * A failed start (not installed, exited, no answer to initialize) is answered from memory for this long, then tried
84	 * again; a changed PATH ends it at once, so installing the server mid-session works. Long enough that a model asking
85	 * again does not spawn a process per call, short enough to notice an install. A judgement.
86	 */
87	export const LSP_START_FAILURE_RECHECK_MS = 30_000;
88	/** A crashed server is started again by the next query, but not sooner than this after the crash; doubled per crash. A judgement. */
89	export const LSP_RESTART_BACKOFF_MS = 1_000;
90	/** Restarts after a crash, per session and server; one more crash and it stays down until PATH changes or Nexus restarts. A judgement. */
91	export const LSP_MAX_RESTARTS = 3;
92	
93	export interface LspTimings {
94	  startMs: number;
95	  queryMs: number;
96	  coldStartMs: number;
97	  quietMs: number;
98	  editSettleMs: number;
99	  retryMs: number;
100	  startRecheckMs: number;
101	  restartBackoffMs: number;
102	  maxRestarts: number;
103	}
104	
105	export const LSP_TIMINGS: Readonly<LspTimings> = Object.freeze({
106	  startMs: LSP_START_TIMEOUT_MS,
107	  queryMs: LSP_WARM_QUERY_TIMEOUT_MS,
108	  coldStartMs: LSP_COLD_START_ALLOWANCE_MS,
109	  quietMs: LSP_PROGRESS_QUIET_MS,
110	  editSettleMs: LSP_EDIT_SETTLE_MS,
111	  retryMs: LSP_READINESS_RETRY_MS,
112	  startRecheckMs: LSP_START_FAILURE_RECHECK_MS,
113	  restartBackoffMs: LSP_RESTART_BACKOFF_MS,
114	  maxRestarts: LSP_MAX_RESTARTS,
115	});
116	
117	/** The last bytes of a server's stderr that are kept, and how much of them a failure report quotes. */
118	const STDERR_RING_BYTES = 4096;
119	const STDERR_TAIL_CHARS = 400;
120	/** After a server's exit, how long its stderr is given to deliver what it still holds (a child of the server can keep the pipe open). */
121	const STDERR_DRAIN_MS = 200;
122	
123	// ------------------------------------------------------------------------------------------------------------ state
124	
125	/**
126	 * Where one server is. `indexing`: it runs but has not finished analysing: work-done progress is in flight or ended
127	 * less than the quiet period ago, or, for a server that reports none, it started less than the cold-start allowance ago
128	 * and has answered nothing yet. A server marked `awaitProgress` is ready only after a progress cycle.
129	 */
130	export type LspServerState = "not_started" | "starting" | "initializing" | "indexing" | "ready" | "failed" | "stopped";
131	
132	export interface LspFailure {
133	  kind: "not_installed" | "spawn_failed" | "exited" | "initialize_timeout" | "crashed" | "crash_loop";
134	  /** One sentence, safe to show: it holds nothing the server wrote. */
135	  message: string;
136	  at: number;
137	  exitCode?: number | null;
138	  signal?: string | null;
139	  /** The end of the server's stderr: untrusted text, already capped, stripped of control characters and redacted. Show it fenced (`failureDetail`). */
140	  stderrTail?: string;
141	}
142	
143	export interface LspServerStatus {
144	  server: string;
145	  state: LspServerState;
146	  /** How long it has been in this state. */
147	  forMs: number;
148	  detail?: string;
149	  cause?: LspFailure;
150	  /** Crashes of this server in this session. */
151	  crashes?: number;
152	}
153	
154	/** What a query returns in place of an answer when the server's state is the reason there is none. */
155	interface NoAnswer {
156	  reason: string;
157	  state?: LspServerStatus;
158	  /** Fenced untrusted text (the server's stderr) to show after the reason. */
159	  detail?: string;
160	}
161	
162	const seconds = (ms: number): string => (ms < 1000 ? `${Math.round(ms)} ms` : `${Math.round(ms / 100) / 10} s`);
163	
164	/** The stderr tail of a failure, fenced as untrusted, or undefined when there is none. */
165	export function failureDetail(cause: LspFailure | undefined): string | undefined {
166	  return cause?.stderrTail ? fenceUntrusted("language server stderr, last output", cause.stderrTail) : undefined;
167	}
168	
169	const noAnswer = (reason: string, state: LspServerStatus): NoAnswer => {
170	  const detail = failureDetail(state.cause);
171	  return { reason, state, ...(detail ? { detail } : {}) };
172	};
173	
174	/** `cmd` as the server's environment would find it, or null. A name is looked up on PATH; a path is taken as given, from `cwd`. */
175	function findCommand(cmd: string, pathVar: string, cwd: string): string | null {
176	  if (process.platform === "win32") return cmd; // extensions and App Paths decide there: left to the spawn, whose error is reported the same way
177	  const executable = (p: string): boolean => {
178	    try {
179	      fs.accessSync(p, fs.constants.X_OK);
180	      return fs.statSync(p).isFile();
181	    } catch {
182	      return false;
183	    }
184	  };
185	  if (cmd.includes("/") || cmd.includes(path.sep)) return executable(path.resolve(cwd, cmd)) ? cmd : null;
186	  for (const dir of pathVar.split(path.delimiter)) if (dir !== "" && executable(path.join(dir, cmd))) return path.join(dir, cmd);
187	  return null;
188	}
189	
190	const timedOut = (err: unknown): boolean => (err as any)?.code === "LSP_TIMEOUT";
191	const cancelled = (err: unknown): boolean => (err as any)?.code === "LSP_CANCELLED";
192	/** LSP `ServerCancelled`: the server abandoned a pull request; its data says whether to ask again. */
193	const SERVER_CANCELLED = -32802;
194	/** How often one diagnostics query asks again after such a cancellation (within its timeout). */
195	const PULL_RETRIGGER_LIMIT = 3;
196	/** Wakes a query waiting for evidence that the server has settled: any publish, the end of a progress cycle, a close. */
197	const ANY_DOCUMENT = "";
198	
199	/** `state` and `detail` are present only when the server's state is why there is no answer. */
200	export type DiagnosticsAnswer = { status: "ok"; diagnostics: LspDiagnostic[] } | { status: "unavailable"; reason: string; state?: LspServerStatus; detail?: string };
201	
202	const toDiagnostics = (items: any[]): LspDiagnostic[] =>
203	  items.map((d: any) => ({
204	    range: d.range,
205	    severity: d.severity === 1 ? "error" : d.severity === 2 ? "warning" : "information",
206	    message: d.message,
207	    source: d.source,
208	    ...(d.code !== undefined && d.code !== null ? { code: d.code } : {}),
209	  }));
210	
211	const SYSTEM_BIN_DIRS = ["/usr/bin", "/bin", "/usr/local/bin", "/sbin", "/usr/sbin"];
212	
213	function realOrNull(p: string): string | null {
214	  try {
215	    return fs.realpathSync(p);
216	  } catch {
217	    return null;
218	  }
219	}
220	
221	/** The containment rule for documents; `child` and `root` are real paths. */
222	const outsideRoot = (root: string, child: string): boolean => {
223	  const rel = path.relative(root, child);
224	  return rel.startsWith("..") || path.isAbsolute(rel);
225	};
226	
227	const isInside = (parent: string, child: string): boolean => {
228	  const rel = path.relative(parent, child);
229	  return rel === "" || (rel !== ".." && !rel.startsWith(".." + path.sep) && !path.isAbsolute(rel));
230	};
231	
232	/**
233	 * The environment a language server starts with: the MCP allowlist (no credentials) plus the toolchain locations the
234	 * servers need. PATH keeps only existing absolute entries that do not resolve (through symlinks) into the workspace, so
235	 * project content cannot supply the binary. When the workspace is a home directory or a system prefix that itself
236	 * contains the toolchain, its entries are kept: dropping them would leave no server installed.
237	 */
238	export function buildLspEnvironment(workspace: string, source: NodeJS.ProcessEnv = process.env): Record<string, string> {
239	  const env = buildMcpEnvironment();
240	  for (const k of LSP_TOOLCHAIN_VARS) if (source[k] !== undefined) env[k] = source[k]!;
241	  for (const [k, v] of Object.entries(env)) {
242	    if (/^(https?|all)_proxy$/i.test(k) && /\/\/[^/]*@/.test(v)) delete env[k];
243	  }
244	  const root = realOrNull(path.resolve(workspace));
245	  const broad =
246	    root !== null &&
247	    [os.homedir(), ...SYSTEM_BIN_DIRS].some((d) => {
248	      const real = realOrNull(d);
249	      return real !== null && isInside(root, real);
250	    });
251	  env.PATH = (env.PATH ?? "")
252	    .split(path.delimiter)
253	    .filter((d) => {
254	      if (!path.isAbsolute(d) || root === null) return false;
255	      const real = realOrNull(d);
256	      return real !== null && (broad || !isInside(root, real));
257	    })
258	    .join(path.delimiter);
259	  return env;
260	}
261	
262	/** Thrown by a query whose file cannot be given to the server; the message is the answer the caller reports. */
263	const unreadable = (filePath: string): Error => new Error(`${filePath} is not a readable file inside the workspace.`);
264	
265	/** One spelling per path for comparisons: no trailing separator, no `.` or `..`, a lower-case drive letter. */
266	const comparablePath = (p: string): string => path.resolve(p).replace(/^[A-Z]:/, (drive) => drive.toLowerCase());
267	
268	interface FileState {
269	  text: string;
270	  /** Device, inode, size, mtime and ctime (ns). ctime is included because an edit can restore size and mtime but not it. */
271	  stamp: string;
272	  /** The stamp alone proves "unchanged" (see STAT_SETTLE_MS); otherwise the next check compares content. */
273	  settled: boolean;
274	}
275	
276	function stampOf(st: fs.BigIntStats, readAtMs: number): Pick<FileState, "stamp" | "settled"> {
277	  const newest = st.mtimeNs > st.ctimeNs ? st.mtimeNs : st.ctimeNs;
278	  return {
279	    stamp: `${st.dev}:${st.ino}:${st.size}:${st.mtimeNs}:${st.ctimeNs}`,
280	    settled: BigInt(readAtMs) * 1_000_000n - newest >= BigInt(STAT_SETTLE_MS) * 1_000_000n,
281	  };
282	}
283	
284	/**
285	 * The regular file at `real` (a path already resolved through symlinks), or null. The descriptor refuses a symlink put in
286	 * the last component since the path was resolved, and does not block on a FIFO; the stamp is of the file actually read.
287	 */
288	function readRegularFile(real: string): FileState | null {
289	  let fd: number | undefined;
290	  try {
291	    const readAtMs = Date.now();
292	    fd = fs.openSync(real, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0) | (fs.constants.O_NONBLOCK ?? 0));
293	    const st = fs.fstatSync(fd, { bigint: true });
294	    if (!st.isFile()) return null;
295	    return { text: fs.readFileSync(fd, "utf-8"), ...stampOf(st, readAtMs) };
296	  } catch {
297	    return null;
298	  } finally {
299	    if (fd !== undefined) fs.closeSync(fd);
300	  }
301	}
302	
303	/** What the server holds for one file. The client's only record of it: every query goes through `LspClient.open`. */
304	interface OpenDocument extends FileState {
305	  /** Identity: the file's real path. Two spellings of one file (a symlink, a symlinked workspace) are one document. */
306	  key: string;
307	  /** The spelling sent to the server, and the paths a server may name it by (as sent, and canonical). */
308	  uri: string;
309	  paths: string[];
310	  /** The version sent with the latest didOpen or didChange. */
311	  version: number;
312	  /** The sequence number of the latest didChange for it; 0 while it is as it was opened. And when that was. */
313	  changedSeq: number;
314	  changedAt: number;
315	  /** The latest list published for this version, and the client sequence number when it arrived. */
316	  diagnostics?: { list: LspDiagnostic[]; seq: number };
317	  /** The last full report pulled for it, kept so that an "unchanged" reply to its `resultId` has a list to stand for. */
318	  pulled?: { list: LspDiagnostic[]; resultId?: string };
319	  /** Diagnostics queries waiting on this document; it is not evicted meanwhile. */
320	  waiting: number;
321	}
322	
323	export interface LspPosition {
324	  line: number;
325	  character: number;
326	}
327	
328	export interface LspRange {
329	  start: LspPosition;
330	  end: LspPosition;
331	}
332	
333	export interface LspLocation {
334	  uri: string;
335	  range: LspRange;
336	}
337	
338	export interface LspServerSpec {
339	  cmd: string;
340	  args?: string[];
341	  languageId: string;
342	  /** Extra variables for this server only; the built-in table never sets it. */
343	  env?: Record<string, string>;
344	  /**
345	   * The server analyses in stages and publishes an empty list before it has finished (rust-analyzer: before the Cargo
346	   * project is loaded and types are analysed). Diagnostics then wait, within the caller's timeout, until the server's own
347	   * progress reports (`$/progress`) have ended, instead of returning on the first publish.
348	   */
349	  awaitProgress?: boolean;
350	  /** Timings that differ for this server (see LSP_TIMINGS). */
351	  timings?: Partial<LspTimings>;
352	  /** One line: how to install it. Shown when it is not found. */
353	  installHint?: string;
354	}
355	
356	export interface LspDiagnostic {
357	  range: LspRange;
358	  severity: "error" | "warning" | "information" | "hint";
359	  message: string;
360	  source?: string;
361	  code?: string | number;
362	}
363	
364	/**
365	 * Lightweight Language Server Protocol Client (Candidate #44)
366	 * Communicates with rust-analyzer, typescript-language-server, pyright via JSON-RPC stdio
367	 */
368	export class LspClient {
369	  public serverCmd: string;
370	  public serverArgs: string[];
371	  public rootPath: string;
372	  /** Open documents by identity (real path), least recently queried first. */
373	  private documents: Map<string, OpenDocument> = new Map();
374	  /** The same documents by the URI sent to the server. */
375	  private opened: Map<string, OpenDocument> = new Map();
376	  /**
377	   * One counter orders everything the client tells the server about content: it supplies each document version (so a
378	   * version is never reused, also not by a document closed and opened again) and stamps each list on arrival.
379	   * `lastChangeSeq` is its value at the latest change of content the server holds: a didChange, or the close of a document
380	   * whose file is gone. A list that arrived before it was computed without that change.
381	   */
382	  private seq = 0;
383	  private lastChangeSeq = 0;
384	  /** The latest change no publish can vouch for any more: its document was closed (deleted, or evicted) before the server published for it. */
385	  private unevidencedSeq = 0;
386	  /** When the server last published diagnostics for any file, and whether it has ever attached a version. */
387	  private lastPublishAt = 0;
388	  private versionedPublishes = false;
389	  /**
390	   * Set when the server offers pull diagnostics (`diagnosticProvider`): a diagnostics query is then a
391	   * `textDocument/diagnostic` request, answered for the content the server holds, and published lists are not consulted.
392	   * `interFileDependencies` and `workspaceDiagnostics` are recorded as announced; workspace diagnostics are not used.
393	   */
394	  public diagnosticProvider: { identifier?: string; interFileDependencies: boolean; workspaceDiagnostics: boolean } | null = null;
395	  private diagnosticWaiters: Map<string, Array<() => void>> = new Map();
396	  private child: ChildProcess | null = null;
397	  private nextId: number = 1;
398	  private pending: Map<number, { resolve: (val: any) => void; reject: (err: any) => void }> = new Map();
399	  private saveOptions?: { includeText?: boolean };
400	  private buffer: Buffer = Buffer.alloc(0);
401	  /** True while the server runs and has answered `initialize`. */
402	  public initialized: boolean = false;
403	  private lifecycle: "not_started" | "starting" | "initializing" | "running" | "failed" | "stopped" = "not_started";
404	  private lifecycleSince = Date.now();
405	  /** Why the server is not running, once it failed to start or crashed. */
406	  public failure?: LspFailure;
407	  /** The last STDERR_RING_BYTES the server wrote to stderr. */
408	  private stderrRing: Buffer = Buffer.alloc(0);
409	  /** Resolves when the process has exited and its stderr has been collected. */
410	  private gone: Promise<void> = Promise.resolve();
411	  /** When `initialize` was answered, and when the analysis now in flight began (the start, or the first progress after a quiet spell). */
412	  private initializedAt = 0;
413	  private busySince = 0;
414	  /** A server that reports no progress has shown that it has loaded the project: it published for an open document or answered a query. */
415	  private answered = false;
416	  /** Tokens of the server's work-done progress that has begun and not ended (with the sequence number at their begin), and when progress last changed. */
417	  private progressActive: Map<string, number> = new Map();
418	  /** The highest sequence number at which a progress cycle that has since ended began: the server finished work it started after every change up to it. */
419	  private progressSettledSeq = 0;
420	  /** Progress cycles that have ended. Nothing resets it or `lastProgressAt`: a query compares them with its own document's change, so syncing another document cannot take a waiting query's evidence away. */
421	  private progressEnded = 0;
422	  private lastProgressAt = 0;
423	
424	  constructor(
425	    serverCmd: string,
426	    rootPath: string,
427	    serverArgs: string[] = [],
428	    private extraEnv: Record<string, string> = {},
429	    private awaitProgress: boolean = false,
430	    private t: LspTimings = LSP_TIMINGS,
431	    private installHint?: string,
432	  ) {
433	    this.serverCmd = serverCmd;
434	    this.serverArgs = serverArgs;
435	    this.rootPath = path.resolve(rootPath);
436	  }
437	
438	  private setLifecycle(next: LspClient["lifecycle"]): void {
439	    this.lifecycle = next;
440	    this.lifecycleSince = Date.now();
441	    this.initialized = next === "running";
442	  }
443	
444	  /** Records why the server is not running (the first reason stands; a deliberate stop is not a failure) and returns it as an error. */
445	  private fail(kind: LspFailure["kind"], message: string, extra: Partial<LspFailure> = {}): Error {
446	    if (this.lifecycle !== "stopped" && this.lifecycle !== "failed") {
447	      this.failure = { kind, message, at: Date.now(), ...extra };
448	      this.setLifecycle("failed");
449	    }
450	    return new Error(this.failure?.message ?? message);
451	  }
452	
453	  /** The end of what the server wrote to stderr, as one line: secrets redacted, control characters and escapes removed, fence markers defused, capped. */
454	  private stderrTail(): string | undefined {
455	    const tail = sanitizeDiagnosticMessage(redactPlain(this.stderrRing.toString("utf-8")).slice(-STDERR_TAIL_CHARS));
456	    return tail === "" ? undefined : tail;
457	  }
458	
459	  /**
460	   * Whether a running server has finished analysing, on the evidence there is, and when it will have if nothing more
461	   * happens (null: not before the server says more).
462	   */
463	  private readiness(now: number): { ready: boolean; detail: string; at: number | null } {
464	    if (this.progressActive.size > 0) return { ready: false, detail: "work-done progress in flight", at: null };
465	    if (this.progressEnded > 0) {
466	      const at = this.lastProgressAt + this.t.quietMs;
467	      return now >= at ? { ready: true, detail: "its progress has ended", at } : { ready: false, detail: "its progress has just ended", at };
468	    }
469	    if (this.awaitProgress) return { ready: false, detail: "it has reported no progress yet", at: null };
470	    if (this.answered) return { ready: true, detail: "it has answered", at: this.initializedAt };
471	    const at = this.initializedAt + this.t.coldStartMs;
472	    return now >= at ? { ready: true, detail: "it reports no progress and its warm-up period is over", at } : { ready: false, detail: "it reports no progress and started a moment ago", at };
473	  }
