484	  /**
485	   * When a call that begins at `now` gives up: after the warm timeout; for a server that is not ready, not before its
486	   * cold-start allowance (counted from its start, so a later call gets what is left of it, not a new one); for a staged
487	   * server's edited document, not before the post-edit settle can end.
488	   */
489	  private deadline(now: number, doc?: OpenDocument): number {
490	    const cold = this.readiness(now).ready ? 0 : this.initializedAt + this.t.coldStartMs;
491	    const edit = doc && this.awaitProgress && doc.changedSeq > 0 ? doc.changedAt + this.t.editSettleMs + this.t.quietMs : 0;
492	    return Math.max(now + this.t.queryMs, cold, edit);
493	  }
