495	  /**
496	   * Starts the server and waits for its answer to `initialize`. Rejects, with `failure` set, when the command is not
497	   * there, the process cannot be executed, it exits first, or it does not answer in time (it is then killed).
498	   */
499	  public async start(): Promise<void> {
500	    this.setLifecycle("starting");
501	    const env = { ...buildLspEnvironment(this.rootPath), ...this.extraEnv };
502	    // Looked up where the server's own environment would find it, before anything is spawned.
503	    const where = /[\\/]/.test(this.serverCmd) ? "" : " on PATH";
504	    const notInstalled = `Language server not installed: ${this.serverCmd} was not found${where}.${this.installHint ? ` Install it with: ${this.installHint}` : ""}`;
505	    if (findCommand(this.serverCmd, env.PATH ?? "", this.rootPath) === null) throw this.fail("not_installed", notInstalled);
506	    let child: ChildProcess;
507	    try {
508	      child = spawn(this.serverCmd, this.serverArgs, { cwd: this.rootPath, env, stdio: ["pipe", "pipe", "pipe"] });
509	    } catch (err: any) {
510	      throw this.fail("spawn_failed", `Language server '${this.serverCmd}' failed to start: it could not be executed (${err.code ?? err.message}).`);
511	    }
512	    this.child = child;
513	    try {
514	      child.stderr?.on("data", (chunk: Buffer) => {
515	        this.stderrRing = (chunk.length >= STDERR_RING_BYTES ? chunk : Buffer.concat([this.stderrRing, chunk])).subarray(-STDERR_RING_BYTES);
516	      });
517	
518	      // The process could not be executed (found, but its interpreter or a library is missing): no exit follows and
519	      // nothing will answer, so whoever waits is told now.
520	      child.on("error", (err: any) => {
521	        const how = this.lifecycle === "running" ? "stopped working" : "failed to start: it could not be executed";
522	        const failure =
523	          err.code === "ENOENT" && process.platform === "win32" // not looked up beforehand there (findCommand)
524	            ? this.fail("not_installed", notInstalled)
525	            : this.fail(this.lifecycle === "running" ? "crashed" : "spawn_failed", `Language server '${this.serverCmd}' ${how} (${err.code ?? err.message}).`);
526	        this.failInFlight(failure);
527	      });
528	      child.on("spawn", () => {
529	        if (this.lifecycle === "starting") this.setLifecycle("initializing");
530	      });
531	
532	      this.gone = new Promise<void>((resolve) => {
533	        child.on("exit", (code, signal) => {
534	          const how = signal ? `killed by ${signal}` : `exit code ${code}`;
535	          const message = this.lifecycle === "running" ? `Language server '${this.serverCmd}' crashed (${how}).` : `Language server '${this.serverCmd}' failed to start: ${how}.`;
536	          this.fail(this.lifecycle === "running" ? "crashed" : "exited", message, { exitCode: code, signal });
537	          this.initialized = false;
538	          // Its last words are still in the pipe: wait for the streams to close, but not for long.
539	          let done = false;
540	          const finish = () => {
541	            if (done) return;
542	            done = true;
543	            clearTimeout(timer);
544	            if (this.failure) this.failure.stderrTail = this.stderrTail();
545	            this.failInFlight(new Error(this.failure?.message ?? `LSP server '${this.serverCmd}' exited`));
546	            resolve();
547	          };
548	          const timer = setTimeout(finish, STDERR_DRAIN_MS);
549	          child.once("close", finish);
550	        });
551	      });
552	      child.stdin?.on("error", () => {
553	        this.initialized = false;
554	      });
555	
556	      child.stdout?.on("data", (data: Buffer) => {
557	        this.handleData(data);
558	      });
559	
560	      const rootUri = pathToFileURL(this.rootPath).href;
561	
562	      // 1. Initialize
563	      const initRes = await this.sendRequest("initialize", {
564	        processId: process.pid,
565	        rootUri,
566	        capabilities: {
567	          textDocument: {
568	            hover: { contentFormat: ["markdown", "plaintext"] },
569	            definition: { dynamicRegistration: true },
570	            // Ask servers to attach document versions so delayed results for pre-edit content can be rejected.
571	            publishDiagnostics: { relatedInformation: true, versionSupport: true },
572	            synchronization: { didSave: true },
573	            // Pull diagnostics, except from a staged server: its lists come from several analyses and arrive by publish;
574	            // a pull would return one of them.
575	            ...(this.awaitProgress ? {} : { diagnostic: { dynamicRegistration: false, relatedDocumentSupport: false } }),
576	          },
577	          ...(this.awaitProgress ? {} : { workspace: { diagnostics: { refreshSupport: true } } }),
578	          // Declared so that servers which report progress (rust-analyzer) send $/progress, which diagnostics wait on.
579	          window: { workDoneProgress: true },
580	        },
581	      }, this.t.startMs);
582	
583	      if (!initRes) throw new Error("it answered initialize with no result");
584	      const sync = initRes.capabilities?.textDocumentSync;
585	      if (typeof sync === "object" && sync?.save) {
586	        this.saveOptions = typeof sync.save === "object" ? sync.save : {};
587	      }
588	      const provider = initRes.capabilities?.diagnosticProvider;
589	      if (!this.awaitProgress && provider && typeof provider === "object") {
590	        this.diagnosticProvider = {
591	          ...(typeof provider.identifier === "string" ? { identifier: provider.identifier } : {}),
592	          interFileDependencies: provider.interFileDependencies === true,
593	          workspaceDiagnostics: provider.workspaceDiagnostics === true,
594	        };
595	      }
596	
597	      // 2. Initialized notification
598	      this.sendNotification("initialized", {});
599	      this.initializedAt = this.busySince = Date.now();
600	      this.setLifecycle("running");
601	    } catch (err: any) {
602	      const failure = timedOut(err)
603	        ? this.fail("initialize_timeout", `Language server '${this.serverCmd}' did not answer initialize within ${seconds(this.t.startMs)}; it was killed.`)
604	        : this.fail("spawn_failed", `Language server '${this.serverCmd}' failed to start: ${err.message}.`);
605	      this.initialized = false;
606	      try {
607	        child.kill("SIGKILL");
608	      } catch {}
609	      if (timedOut(err)) {
610	        // What a server that hung wrote to stderr belongs in the report: wait for the kill to land.
611	        let timer: NodeJS.Timeout | undefined;
612	        await Promise.race([this.gone, new Promise<void>((r) => (timer = setTimeout(r, 2 * STDERR_DRAIN_MS)))]);
613	        clearTimeout(timer);
614	      }
615	      throw failure;
616	    }
617	  }
