619	  /** Rejects every request still waiting and wakes every diagnostics waiter: the server is gone, so no answer is coming. */
620	  private failInFlight(err: Error): void {
621	    for (const { reject } of this.pending.values()) reject(err);
622	    this.pending.clear();
623	    const waiters = [...this.diagnosticWaiters.values()].flat();
624	    this.diagnosticWaiters.clear();
625	    for (const w of waiters) w();
626	  }
