839	  /** `gone`: the file is no longer there for the server to read, which changes what other files' answers are computed from. */
840	  private close(doc: OpenDocument, gone: boolean): void {
841	    this.documents.delete(doc.key);
842	    this.opened.delete(doc.uri);
843	    if (gone) this.unevidencedSeq = this.lastChangeSeq = ++this.seq;
844	    else if (!doc.diagnostics) this.unevidencedSeq = Math.max(this.unevidencedSeq, doc.changedSeq);
845	    this.sendNotification("textDocument/didClose", { textDocument: { uri: doc.uri } });
846	    this.wake(doc.key);
847	    this.wake(ANY_DOCUMENT);
848	  }
