850	  /**
851	   * Makes every open document match the disk: a file whose content moved gets a full-text didChange (and didSave where
852	   * the server asked for it); one that is gone, is no longer a regular file, or no longer resolves to itself inside the
853	   * workspace (renamed, or replaced by a symlink) is closed without being read.
854	   * Per document: one realpath and one stat; the content is read only when the stamp moved or cannot be trusted yet.
855	   */
856	  private resync(realRoot: string | null): void {
857	    for (const doc of [...this.documents.values()]) {
858	      let state: FileState | null = null;
859	      if (realRoot !== null && realOrNull(doc.key) === doc.key && !outsideRoot(realRoot, doc.key)) {
860	        try {
861	          const st = fs.statSync(doc.key, { bigint: true });
862	          if (doc.settled && stampOf(st, 0).stamp === doc.stamp) continue;
863	          if (st.isFile()) state = readRegularFile(doc.key);
864	        } catch {}
865	      }
866	      if (!state) this.close(doc, true);
867	      else if (state.text !== doc.text) this.change(doc, state);
868	      else Object.assign(doc, state);
869	    }
870	  }
