872	  /**
873	   * The one way a query reaches a file: brings every open document up to date with the disk, then opens `filePath` if
874	   * the server does not hold it yet and closes the least recently queried documents beyond the bound.
875	   * Throws when the file cannot be read or lies outside the workspace.
876	   */
877	  private open(filePath: string, languageId: string): OpenDocument {
878	    // Resolve symlinks before the containment check: a link inside the workspace must not read a file outside it.
879	    const realRoot = realOrNull(this.rootPath);
880	    this.resync(realRoot);
881	    const key = realRoot === null ? null : realOrNull(path.resolve(this.rootPath, filePath));
882	    if (realRoot === null || key === null || outsideRoot(realRoot, key)) throw unreadable(filePath);
883	    let doc = this.documents.get(key);
884	    if (doc) {
885	      this.documents.delete(key);
886	    } else {
887	      const state = readRegularFile(key);
888	      if (!state) throw unreadable(filePath);
889	      // Named as the workspace was given to the server (its rootUri), so a server that relates documents to the root by
890	      // prefix finds them inside it; below the root the real path, so one file has one name.
891	      const sent = path.join(this.rootPath, path.relative(realRoot, key));
892	      doc = { ...state, key, uri: pathToFileURL(sent).href, paths: [comparablePath(sent), comparablePath(key)], version: ++this.seq, changedSeq: 0, changedAt: 0, waiting: 0 };
893	      this.opened.set(doc.uri, doc);
894	      this.sendNotification("textDocument/didOpen", { textDocument: { uri: doc.uri, languageId, version: doc.version, text: doc.text } });
895	    }
896	    this.documents.set(key, doc);
897	    for (const old of this.documents.values()) {
898	      if (this.documents.size <= MAX_OPEN_DOCUMENTS) break;
899	      // What the server held was just checked against the disk, so closing it changes nothing the server computes from.
900	      if (old !== doc && old.waiting === 0) this.close(old, false);
901	    }
902	    return doc;
903	  }
