905	  /**
906	   * Push-only servers: when a list that arrived at `listSeq`, before a later change to another document, may be taken as
907	   * still current, or null while nothing shows that the server has dealt with that change. Silence is not evidence:
908	   *  - a staged server: a progress cycle that began after the latest change has ended, nothing is in progress, and
909	   *    progress has been quiet for the quiet period;
910	   *  - any other server: it has published for every document changed since the list arrived (that publish shows it
911	   *    analysed the change), and has published nothing for PUBLISH_QUIET_MS.
912	   * Known limit: a server that publishes for the changed document, stays silent for longer than the window, and only
913	   * then publishes a different list for this document has its old list returned as current once. A server that offers
914	   * pull diagnostics is asked instead and has no such window.
915	   */
916	  private settledAt(listSeq: number): number | null {
917	    if (this.awaitProgress) {
918	      return this.progressSettledSeq >= this.lastChangeSeq && this.progressActive.size === 0 ? this.lastProgressAt + this.t.quietMs : null;
919	    }
920	    if (this.unevidencedSeq > listSeq) return null;
921	    for (const doc of this.documents.values()) if (doc.changedSeq > listSeq && !doc.diagnostics) return null;
922	    return this.lastPublishAt + PUBLISH_QUIET_MS;
923	  }
