925	  /**
926	   * Staged servers: when the list held for `doc` is final, or null while the server has shown nothing that says so.
927	   * Such a server publishes an empty list before it has analysed anything, so a list alone is never the evidence:
928	   *  - a progress cycle has ended, nothing is in progress, and progress has been quiet for the quiet period; and
929	   *  - for a document that changed: one such cycle began after the change, or (a server that checks nothing on save)
930	   *    the post-edit settle has passed since the change.
931	   */
932	  private analysedAt(doc: OpenDocument): number | null {
933	    if (this.progressActive.size > 0 || this.progressEnded === 0) return null;
934	    const quietAt = this.lastProgressAt + this.t.quietMs;
935	    if (doc.changedSeq === 0 || this.progressSettledSeq >= doc.changedSeq) return quietAt;
936	    return Math.max(quietAt, doc.changedAt + this.t.editSettleMs);
937	  }
938	
939	  /**
940	   * The diagnostics for the file as it is on disk now, or why there are none to report.
941	   * From a server that offers pull diagnostics: its reply to a request made after the sync.
942	   * Otherwise from what it published: a list counts when it arrived after the latest change the client had sent when
943	   * this call began (and, where the server attaches versions, for this document's version), or when it is older than a
944	   * change to another document and `settledAt` says the server has dealt with that change. From a staged server such a
945	   * list counts only once `analysedAt` says it is final: when the time runs out first the answer is "unavailable, still
946	   * analysing", never the list so far. `timeoutMs`: the caller's own limit; without one the call ends at `deadline`.
947	   * Throws for an unreadable file.
948	   */
949	  public async waitForDiagnostics(filePath: string, languageId: string, timeoutMs?: number, signal?: AbortSignal): Promise<DiagnosticsAnswer> {
950	    const doc = this.open(filePath, languageId);
951	    const startedAt = Date.now();
952	    const limit = timeoutMs ?? this.deadline(startedAt, doc) - startedAt;
953	    if (this.diagnosticProvider) return this.pullDiagnostics(doc, filePath, limit, this.diagnosticProvider.identifier, signal);
954	    const key = doc.key;
955	    const since = this.lastChangeSeq;
956	    const held = () => this.documents.get(key)?.diagnostics;
957	    const current = (): LspDiagnostic[] | null => {
958	      const d = held();
959	      return d && d.seq >= since ? d.list : null;
960	    };
961	    const stands = (now: number): LspDiagnostic[] | null => {
962	      const d = held();
963	      const at = d ? this.settledAt(d.seq) : null;
964	      return d && at !== null && now >= at ? d.list : null;
965	    };
966	    /** A current list from a staged server is the answer only once the server has finished. */
967	    const final = (now: number): boolean => {
968	      if (!this.awaitProgress) return true;
969	      const at = this.analysedAt(doc);
970	      return at !== null && now >= at;
971	    };
972	    doc.waiting++;
973	    try {
974	      for (let now = startedAt; now - startedAt < limit && !signal?.aborted; now = Date.now()) {
975	        const left = limit - (now - startedAt);
976	        let at: number | null;
977	        if (current()) {
978	          if (final(now)) break;
979	          at = this.analysedAt(doc);
980	        } else {
981	          if (stands(now)) break;
982	          // No list: wait for one. A list from before another document's change: wait for the server to publish or end
983	          // progress, or for the moment its quiet period is over.
984	          const d = held();
985	          at = d ? this.settledAt(d.seq) : null;
986	          if (!d) {
987	            await this.nextPublish(key, left, signal);
988	            if (!this.documents.has(key) || !this.initialized) break; // closed, or the server is gone
989	            continue;
990	          }
991	        }
992	        // Woken by any publish and any progress report; otherwise at the moment the quiet period is over.
993	        await this.nextPublish(ANY_DOCUMENT, at === null ? left : Math.min(left, Math.max(1, at - now)), signal);
994	        if (!this.documents.has(key) || !this.initialized) break;
995	      }
996	      const now = Date.now();
997	      const status = this.status(now);
998	      const unavailable = (reason: string): DiagnosticsAnswer => ({ status: "unavailable", reason, ...(status.state === "ready" ? {} : noAnswer(reason, status)) });
999	      if (signal?.aborted) return { status: "unavailable", reason: `The diagnostics query for ${filePath} was cancelled.` };
1000	      const list = current();
1001	      if (list && final(now)) return { status: "ok", diagnostics: list };
1002	      const stood = list ? null : stands(now);
1003	      if (stood) return { status: "ok", diagnostics: stood };
1004	      if (this.lifecycle !== "running") return unavailable(`${this.failure?.message ?? `Language server '${this.serverCmd}' was stopped.`} No diagnostics for ${filePath}.`);
1005	      const busy = `after ${seconds(status.forMs)} (${status.detail})`;
1006	      if (list) return unavailable(`Language server '${this.serverCmd}' is still analysing ${busy}; what it has published for ${filePath} so far is not final. Ask again shortly.`);
1007	      const what = held() ? `for ${filePath} after another open file changed,` : `for ${filePath}`;
1008	      const indexing = status.state === "indexing" ? ` It is still indexing ${busy}; ask again shortly.` : "";
1009	      return unavailable(`Language server '${this.serverCmd}' published no diagnostics ${what} within ${limit}ms.${indexing}`);
1010	    } finally {
1011	      doc.waiting--;
1012	    }
1013	  }
1014	
1015	  /**
1016	   * One `textDocument/diagnostic` exchange. A full report is the answer and is kept with its `resultId`; "unchanged" is
1017	   * an answer only for the kept list that `resultId` was sent for. Reports for related documents are not used. Asked
1018	   * again when the server cancels with `retriggerRequest`, a bounded number of times within the timeout.
1019	   */
1020	  private async pullDiagnostics(doc: OpenDocument, filePath: string, timeoutMs: number, identifier?: string, signal?: AbortSignal): Promise<DiagnosticsAnswer> {
1021	    const deadline = Date.now() + timeoutMs;
1022	    const unavailable = (why: string): DiagnosticsAnswer => ({ status: "unavailable", reason: `Language server '${this.serverCmd}' gave no diagnostics for ${filePath}: ${why}` });
1023	    for (let attempt = 0; ; attempt++) {
1024	      const previousResultId = doc.pulled?.resultId;
1025	      let report: any;
1026	      try {
1027	        report = await this.sendRequest(
1028	          "textDocument/diagnostic",
1029	          { textDocument: { uri: doc.uri }, ...(identifier !== undefined ? { identifier } : {}), ...(previousResultId !== undefined ? { previousResultId } : {}) },
1030	          Math.max(1, deadline - Date.now()),
1031	          signal,
1032	        );
1033	      } catch (err: any) {
1034	        if (err.code === SERVER_CANCELLED && err.data?.retriggerRequest === true && attempt < PULL_RETRIGGER_LIMIT && Date.now() < deadline) continue;
1035	        return unavailable(`${err.message}.`);
1036	      }
1037	      if (report?.kind === "full" && Array.isArray(report.items)) {
1038	        doc.pulled = { list: toDiagnostics(report.items), ...(typeof report.resultId === "string" ? { resultId: report.resultId } : {}) };
1039	        this.answered = true;
1040	        return { status: "ok", diagnostics: doc.pulled.list };
1041	      }
1042	      if (report?.kind === "unchanged" && previousResultId !== undefined) {
1043	        if (doc.pulled) {
1044	          if (typeof report.resultId === "string") doc.pulled.resultId = report.resultId;
1045	          return { status: "ok", diagnostics: doc.pulled.list };
1046	        }
1047	        // The kept list was dropped while the request was out (workspace/diagnostic/refresh): ask for a full report.
1048	        if (attempt < PULL_RETRIGGER_LIMIT && Date.now() < deadline) continue;
1049	      }
1050	      return unavailable("its report was neither a full list nor 'unchanged' for a list this client holds.");
1051	    }
1052	  }
1053	
1054	  /** Resolves when a list is accepted for the document, when it is closed, when the server is gone, at the timeout, or when `signal` fires. */
1055	  private nextPublish(key: string, timeoutMs: number, signal?: AbortSignal): Promise<void> {
1056	    return new Promise<void>((resolve) => {
1057	      const leave = () => {
1058	        clearTimeout(timer);
1059	        signal?.removeEventListener("abort", giveUp);
1060	        resolve();
1061	      };
1062	      const giveUp = () => {
1063	        const list = this.diagnosticWaiters.get(key)?.filter((w) => w !== leave) ?? [];
1064	        if (list.length) this.diagnosticWaiters.set(key, list);
1065	        else this.diagnosticWaiters.delete(key);
1066	        leave();
1067	      };
1068	      const timer = setTimeout(giveUp, timeoutMs);
1069	      this.diagnosticWaiters.set(key, [...(this.diagnosticWaiters.get(key) ?? []), leave]);
1070	      if (signal?.aborted) giveUp();
1071	      else signal?.addEventListener("abort", giveUp, { once: true });
1072	    });
1073	  }
1074	
1075	  public pid(): number | undefined {
1076	    return this.child?.pid;
1077	  }
1078	
1079	  /** Opens the file (if it is readable) so that the server starts on its project; false when it cannot be given to the server. */
1080	  public prepare(filePath: string, languageId: string): boolean {
1081	    try {
1082	      this.open(filePath, languageId);
1083	      return true;
1084	    } catch {
1085	      return false;
1086	    }
1087	  }
1088	
1089	  /**
1090	   * One request about a position, with the readiness rule: an answer with content is the answer; an empty one is "there
1091	   * is nothing here" only from a server that is ready. While it is not, the request is made again when its progress
1092	   * moves, or after a pause that doubles (a server that reports none), until the call's deadline; `notReady` then says
1093	   * what state the server was left in. A request that fails on a ready server, or for another reason than a timeout, throws.
1094	   */
1095	  private async ask(method: string, filePath: string, languageId: string, line: number, character: number, empty: (result: any) => boolean, signal?: AbortSignal): Promise<{ result: any; notReady: LspServerStatus | null }> {
1096	    const doc = this.open(filePath, languageId);
1097	    const params = { textDocument: { uri: doc.uri }, position: { line: Math.max(0, line - 1), character: Math.max(0, character - 1) } };
1098	    const deadline = this.deadline(Date.now());
1099	    for (let pause = this.t.retryMs; ; pause = Math.min(pause * 2, READINESS_RETRY_CAP_MS)) {
1100	      let result: any = null;
1101	      let failed: unknown;
1102	      try {
1103	        result = await this.sendRequest(method, params, this.t.queryMs, signal);
1104	      } catch (err) {
1105	        failed = err;
1106	      }
1107	      if (failed === undefined && !empty(result)) {
1108	        if (!this.awaitProgress) this.answered = true;
1109	        return { result, notReady: null };
1110	      }
1111	      const now = Date.now();
1112	      const ready = this.lifecycle === "running" && this.readiness(now).ready;
1113	      if (failed !== undefined && (ready || !timedOut(failed))) throw failed;
1114	      if (ready) return { result, notReady: null };
1115	      if (now >= deadline) return { result: null, notReady: this.status(now) };
1116	      await this.nextPublish(ANY_DOCUMENT, Math.min(deadline - now, pause), signal);

