164	/** The stderr tail of a failure, fenced as untrusted, or undefined when there is none. */
165	export function failureDetail(cause: LspFailure | undefined): string | undefined {
166	  return cause?.stderrTail ? fenceUntrusted("language server stderr, last output", cause.stderrTail) : undefined;
167	}
