190	const timedOut = (err: unknown): boolean => (err as any)?.code === "LSP_TIMEOUT";
191	const cancelled = (err: unknown): boolean => (err as any)?.code === "LSP_CANCELLED";
192	/** LSP `ServerCancelled`: the server abandoned a pull request; its data says whether to ask again. */
193	const SERVER_CANCELLED = -32802;
194	/** How often one diagnostics query asks again after such a cancellation (within its timeout). */
195	const PULL_RETRIGGER_LIMIT = 3;
196	/** Wakes a query waiting for evidence that the server has settled: any publish, the end of a progress cycle, a close. */
197	const ANY_DOCUMENT = "";
