211	const SYSTEM_BIN_DIRS = ["/usr/bin", "/bin", "/usr/local/bin", "/sbin", "/usr/sbin"];
212	
213	function realOrNull(p: string): string | null {
214	  try {
215	    return fs.realpathSync(p);
216	  } catch {
217	    return null;
218	  }
219	}
