221	/** The containment rule for documents; `child` and `root` are real paths. */
222	const outsideRoot = (root: string, child: string): boolean => {
223	  const rel = path.relative(root, child);
224	  return rel.startsWith("..") || path.isAbsolute(rel);
225	};
226	
227	const isInside = (parent: string, child: string): boolean => {
228	  const rel = path.relative(parent, child);
229	  return rel === "" || (rel !== ".." && !rel.startsWith(".." + path.sep) && !path.isAbsolute(rel));
230	};
