262	/** Thrown by a query whose file cannot be given to the server; the message is the answer the caller reports. */
263	const unreadable = (filePath: string): Error => new Error(`${filePath} is not a readable file inside the workspace.`);
264	
265	/** One spelling per path for comparisons: no trailing separator, no `.` or `..`, a lower-case drive letter. */
266	const comparablePath = (p: string): string => path.resolve(p).replace(/^[A-Z]:/, (drive) => drive.toLowerCase());
