546	            resolve();
547	          };
548	          const timer = setTimeout(finish, STDERR_DRAIN_MS);
549	          child.once("close", finish);
550	        });
551	      });
552	      child.stdin?.on("error", () => {
553	        this.initialized = false;
554	      });
555	
556	      child.stdout?.on("data", (data: Buffer) => {
