628	  /** A server that sends more than the cap in one message, or buffers past it, is dropped rather than trusted with memory. */
629	  private dropOversized(): void {
630	    this.buffer = Buffer.alloc(0);
631	    this.failInFlight(this.fail("crashed", `Language server '${this.serverCmd}' exceeded the ${LSP_MAX_BUFFER_BYTES}-byte message limit; it was killed.`));
632	    this.initialized = false;
633	    try {
634	      this.child?.kill("SIGKILL");
635	    } catch {}
636	  }
