638	  private handleData(chunk: Buffer): void {
639	    this.buffer = Buffer.concat([this.buffer, chunk]);
640	
641	    while (true) {
642	      const headerEnd = this.buffer.indexOf("\r\n\r\n");
643	      if (headerEnd === -1) break;
644	
645	      const header = this.buffer.subarray(0, headerEnd).toString("latin1");
646	      const match = header.match(/Content-Length:\s*(\d+)/i);
647	      if (!match) {
648	        this.buffer = this.buffer.subarray(headerEnd + 4);
649	        continue;
650	      }
651	
652	      const contentLength = parseInt(match[1], 10);
653	      if (contentLength > LSP_MAX_BUFFER_BYTES) return this.dropOversized();
654	      const bodyStart = headerEnd + 4;
655	
656	      if (this.buffer.length < bodyStart + contentLength) {
657	        // Incomplete body, wait for next chunk
658	        break;
659	      }
660	
661	      const body = this.buffer.subarray(bodyStart, bodyStart + contentLength).toString("utf-8");
662	      this.buffer = this.buffer.subarray(bodyStart + contentLength);
663	
664	      try {
665	        const msg = JSON.parse(body);
666	        if (typeof msg.method === "string" && msg.id !== undefined) {
667	          // A request FROM the server (it has a method; its id space is its own, so it can collide with ours): answer it, or
668	          // a server that waits for the reply (window/workDoneProgress/create, workspace/configuration) can stall.
669	          this.answerServerRequest(msg);
670	          continue;
671	        }
672	        if (msg.method === "$/progress" && msg.params) {
673	          const token = String(msg.params.token);
674	          const kind = msg.params.value?.kind;
675	          if (kind === "begin") {
676	            // Work that begins after a quiet spell is a new analysis; phases that follow one another are one.
677	            if (this.progressActive.size === 0 && this.progressEnded > 0 && Date.now() - this.lastProgressAt >= this.t.quietMs) this.busySince = Date.now();
678	            this.progressActive.set(token, this.seq);
679	          } else if (kind === "end") {
680	            this.progressSettledSeq = Math.max(this.progressSettledSeq, this.progressActive.get(token) ?? 0);
681	            if (this.progressActive.delete(token)) this.progressEnded++;
682	          }
683	          this.lastProgressAt = Date.now();
684	          this.wake(ANY_DOCUMENT);
685	          continue;
686	        }
687	        if (msg.id !== undefined && this.pending.has(msg.id)) {
688	          const { resolve, reject } = this.pending.get(msg.id)!;
689	          this.pending.delete(msg.id);
690	          if (msg.error) {
691	            reject(Object.assign(new Error(msg.error.message || JSON.stringify(msg.error)), { code: msg.error.code, data: msg.error.data }));
692	          } else {
693	            resolve(msg.result);
694	          }
695	        } else if (msg.method === "textDocument/publishDiagnostics") {
696	          const params = msg.params;
697	          if (params && params.uri && Array.isArray(params.diagnostics)) {
698	            this.lastPublishAt = Date.now();
699	            this.wake(ANY_DOCUMENT);
700	            // A list is an answer only for a document the server holds from this client: one published for a file before
701	            // its first open, or after its close, describes content the client never sent and is not kept.
702	            const current = this.documentForUri(params.uri);
703	            if (!current) continue;
704	            if (typeof params.version === "number") {
705	              this.versionedPublishes = true;
706	              if (params.version !== current.version) continue; // published for an older version of the file than the server was last told about
707	            } else if (this.versionedPublishes) {
708	              // A server that attaches versions does so for every open document: once it has, a list without one is not
709	              // about a document as this client sent it (a "cleared" list after a close, arriving after the reopen).
710	              continue;
711	            }
712	            current.diagnostics = { list: toDiagnostics(params.diagnostics), seq: this.seq };
713	            if (!this.awaitProgress) this.answered = true;
714	            this.wake(current.key);
715	          }
716	        }
717	      } catch {}
718	    }
719	    if (this.buffer.length > LSP_MAX_BUFFER_BYTES + 1024) this.dropOversized();
720	  }
