722	  /**
723	   * One request. It ends with the answer, at the timeout, when `signal` fires, or when the server is gone. A request
724	   * given up on (timeout, cancellation) is withdrawn with `$/cancelRequest`, so the server stops working on it.
725	   */
726	  public async sendRequest(method: string, params: any, timeoutMs: number = 8000, signal?: AbortSignal): Promise<any> {
727	    if (!this.child || !this.child.stdin || this.child.killed || this.child.exitCode !== null) {
728	      throw new Error(`LSP server '${this.serverCmd}' is not running`);
729	    }
730	    const cancelledError = () => Object.assign(new Error(`LSP request '${method}' was cancelled`), { code: "LSP_CANCELLED" });
731	    if (signal?.aborted) throw cancelledError();
732	
733	    const id = this.nextId++;
734	    const payload = JSON.stringify({
735	      jsonrpc: "2.0",
736	      id,
737	      method,
738	      params,
739	    });
740	
741	    const header = `Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n`;
742	
743	    return new Promise((resolve, reject) => {
744	      const settle = () => {
745	        clearTimeout(timer);
746	        signal?.removeEventListener("abort", onAbort);
747	      };
748	      const abandon = (err: Error) => {
749	        if (!this.pending.delete(id)) return;
750	        settle();
751	        if (method !== "initialize") this.sendNotification("$/cancelRequest", { id });
752	        reject(err);
753	      };
754	      const timer = setTimeout(() => abandon(Object.assign(new Error(`LSP request '${method}' timed out after ${timeoutMs}ms`), { code: "LSP_TIMEOUT" })), timeoutMs);
755	      const onAbort = () => abandon(cancelledError());
756	      signal?.addEventListener("abort", onAbort, { once: true });
757	
758	      this.pending.set(id, {
759	        resolve: (val) => {
760	          settle();
761	          resolve(val);
762	        },
763	        reject: (err) => {
764	          settle();
765	          reject(err);
766	        },
767	      });
768	
769	      this.child!.stdin!.write(header + payload);
770	    });
771	  }
