773	  private answerServerRequest(msg: { id: number | string; method: string; params?: any }): void {
774	    if (!this.child || !this.child.stdin || this.child.killed || this.child.exitCode !== null) return;
775	    // The server's results changed for a reason the client did not cause: no kept report may stand in for a new one.
776	    if (msg.method === "workspace/diagnostic/refresh") for (const doc of this.documents.values()) doc.pulled = undefined;
777	    // Nothing is configured or registered on the server's behalf: an empty answer is a valid one for the requests servers send.
778	    const result = msg.method === "workspace/configuration" && Array.isArray(msg.params?.items) ? msg.params.items.map(() => null) : null;
779	    const payload = JSON.stringify({ jsonrpc: "2.0", id: msg.id, result });
780	    this.child.stdin.write(`Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n${payload}`);
781	  }
