783	  public sendNotification(method: string, params: any): void {
784	    if (!this.child || !this.child.stdin || this.child.killed || this.child.exitCode !== null) return;
785	    const payload = JSON.stringify({
786	      jsonrpc: "2.0",
787	      method,
788	      params,
789	    });
790	    const header = `Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n`;
791	    this.child.stdin.write(header + payload);
