794	  /**
795	   * The open document a server means by `uri`. Servers do not echo the client's spelling: they may publish under the real
796	   * path where the client sent a symlinked one, and percent-encode differently, so a URI that is not the one sent is
797	   * decoded to a path and compared with the two paths each document goes by. No file-system access.
798	   */
799	  private documentForUri(uri: unknown): OpenDocument | undefined {
800	    if (typeof uri !== "string") return undefined;
801	    const exact = this.opened.get(uri);
802	    if (exact) return exact;
803	    let named: string;
804	    try {
805	      named = comparablePath(fileURLToPath(uri));
806	    } catch {
807	      return undefined; // not a file URI
808	    }
809	    for (const doc of this.documents.values()) if (doc.paths.includes(named)) return doc;
810	    return undefined;
