820	  private change(doc: OpenDocument, state: FileState): void {
821	    Object.assign(doc, state);
822	    doc.version = doc.changedSeq = this.lastChangeSeq = ++this.seq;
823	    doc.diagnostics = undefined;
824	    // Progress that ended before this change does not vouch for the new version: `analysedAt` compares the cycles
825	    // with this document's `changedSeq`. The server's progress record itself is left alone (other queries count on it).
826	    doc.changedAt = Date.now();
827	    this.sendNotification("textDocument/didChange", {
828	      textDocument: { uri: doc.uri, version: doc.version },
829	      contentChanges: [{ text: doc.text }],
830	    });
831	    if (this.saveOptions) {
832	      this.sendNotification("textDocument/didSave", {
833	        textDocument: { uri: doc.uri },
834	        ...(this.saveOptions.includeText ? { text: doc.text } : {}),
835	      });
836	    }
837	  }
