989	            continue;
990	          }
991	        }
992	        // Woken by any publish and any progress report; otherwise at the moment the quiet period is over.
993	        await this.nextPublish(ANY_DOCUMENT, at === null ? left : Math.min(left, Math.max(1, at - now)), signal);
