1001	      if (list && final(now)) return { status: "ok", diagnostics: list };
1002	      const stood = list ? null : stands(now);
1003	      if (stood) return { status: "ok", diagnostics: stood };
1004	      if (this.lifecycle !== "running") return unavailable(`${this.failure?.message ?? `Language server '${this.serverCmd}' was stopped.`} No diagnostics for ${filePath}.`);
1005	      const busy = `after ${seconds(status.forMs)} (${status.detail})`;
1006	      if (list) return unavailable(`Language server '${this.serverCmd}' is still analysing ${busy}; what it has published for ${filePath} so far is not final. Ask again shortly.`);
