22	/**
23	 * Extracts compiler and test diagnostics from raw command output.
24	 */
25	export function extractCompilerDiagnostics(output: string): Diagnostic[] {
26	  if (!output || typeof output !== "string") {
27	    return [];
28	  }
29	
30	  const diagnostics: Diagnostic[] = [];
31	  const seen = new Set<string>();
32	
33	  const addDiag = (d: Diagnostic) => {
34	    const key = `${d.file}:${d.line || 0}:${d.message}`;
35	    if (!seen.has(key)) {
36	      seen.add(key);
37	      diagnostics.push(d);
38	    }
39	  };
40	
41	  // 1. Rust / cargo error parsing:
42	  // error[E0308]: mismatched types
43	  //  --> src/main.rs:12:5
44	  const rustRegex = /error(?:\[(E\d+)\])?: ([^\n]+)\n\s+--> ([^\s:]+):(\d+):(\d+)/g;
45	  let match: RegExpExecArray | null;
46	  while ((match = rustRegex.exec(output)) !== null) {
47	    addDiag({
48	      code: match[1],
49	      message: match[2].trim(),
50	      file: match[3],
51	      line: parseInt(match[4], 10),
52	      column: parseInt(match[5], 10),
53	      severity: "error",
54	    });
55	  }
56	
57	  // 2. TypeScript / tsc error parsing:
58	  // src/index.ts:14:5 - error TS2322: Type 'number' is not assignable to type 'string'.
59	  // or src/index.ts(14,5): error TS2322: ...
60	  const tsRegex1 = /([^\s()]+\.(?:ts|tsx|js|jsx)):(\d+):(\d+) - (error|warning) (TS\d+): ([^\n]+)/g;
61	  while ((match = tsRegex1.exec(output)) !== null) {
62	    addDiag({
63	      file: match[1],
64	      line: parseInt(match[2], 10),
65	      column: parseInt(match[3], 10),
66	      severity: match[4] as "error" | "warning",
67	      code: match[5],
68	      message: match[6].trim(),
69	    });
70	  }
71	
72	  const tsRegex2 = /([^\s()]+\.(?:ts|tsx|js|jsx))\(([0-9]+),([0-9]+)\): (error|warning) (TS[0-9]+): ([^\n]+)/g;
73	  while ((match = tsRegex2.exec(output)) !== null) {
74	    addDiag({
75	      file: match[1],
76	      line: parseInt(match[2], 10),
77	      column: parseInt(match[3], 10),
78	      severity: match[4] as "error" | "warning",
79	      code: match[5],
80	      message: match[6].trim(),
81	    });
82	  }
83	
84	  // 3. Python / pytest traceback & test failures:
85	  // FAILED tests/test_foo.py::test_bar - AssertionError: ...
86	  const pytestRegex = /(?:FAILED|ERROR)\s+([^\s:]+\.py)(?:::(\S+))?\s*(?:-\s*([^\n]+))?/g;
87	  while ((match = pytestRegex.exec(output)) !== null) {
88	    addDiag({
89	      file: match[1],
90	      message: match[3] ? `${match[2] || "test"}: ${match[3].trim()}` : `Test failure in ${match[2] || match[1]}`,
91	      severity: "error",
92	    });
93	  }
94	
95	  // Python Traceback line: File "foo.py", line 42, in ...
96	  const pyTracebackRegex = /File "([^"]+\.py)", line (\d+)(?:, in [^\n]+)?\n\s*([^\n]+)\n\s*([A-Za-z]+Error: [^\n]+)/g;
97	  while ((match = pyTracebackRegex.exec(output)) !== null) {
98	    addDiag({
99	      file: match[1],
100	      line: parseInt(match[2], 10),
101	      message: match[4].trim(),
102	      severity: "error",
103	    });
104	  }
105	
106	  // 4. Standard GCC / Clang / Go error format:
107	  // file.c:12:5: error: expected ';'
108	  // file.go:12:5: undefined: foo
109	  const genericRegex = /([^\s:]+\.[a-zA-Z0-9_]+):(\d+):(\d+):\s*(?:(error|warning):\s*)?([^\n]+)/g;
110	  while ((match = genericRegex.exec(output)) !== null) {
111	    // Avoid double-matching rust or ts lines
112	    if (!match[1].endsWith(".rs") && !match[1].endsWith(".ts") && !match[1].endsWith(".tsx")) {
113	      addDiag({
114	        file: match[1],
115	        line: parseInt(match[2], 10),
116	        column: parseInt(match[3], 10),
117	        severity: (match[4] === "warning" ? "warning" : "error"),
118	        message: match[5].trim(),
119	      });
120	    }
121	  }
122	
123	  // 5. Node.js AssertionError with stack trace
124	  const nodeAssertRegex = /AssertionError(?: \[[^\]]+\])?: ([^\n]+)[\s\S]*?at [^\n]+ \(([^:]+\.(?:test|spec)\.[a-zA-Z0-9_]+):(\d+):(\d+)\)/;
125	  const nodeMatch = nodeAssertRegex.exec(output);
126	  if (nodeMatch) {
127	    addDiag({
128	      file: nodeMatch[2],
129	      line: parseInt(nodeMatch[3], 10),
130	      column: parseInt(nodeMatch[4], 10),
131	      severity: "error",
132	      message: `Assertion failure: ${nodeMatch[1].trim()}`,
133	    });
134	  }
135	
136	  return diagnostics;
137	}
