142	export function formatDiagnosticHints(diagnostics: Diagnostic[], workspace?: string): string {
143	  if (!diagnostics || diagnostics.length === 0) {
144	    return "";
145	  }
146	
147	  const records = compilerDiagnosticRecords(diagnostics, workspace);
148	  const lines = records.slice(0, 10).map((d) => {
149	    const loc = d.line ? `:${d.line}${d.column ? `:${d.column}` : ""}` : "";
150	    const code = d.code ? ` [${d.code}]` : "";
151	    return `- ${d.file}${loc} (${d.tool})${code}: ${d.message}`;
152	  });
153	  if (records.length > 10) lines.push(`+${records.length - 10} more`);
154	  return [
155	    "\n\n[Automated Diagnostic Hints & Error Locations]:",
156	    fenceUntrusted("compiler diagnostics", lines.join("\n")),
157	    "Tip: Use `read_file` or `edit_file` to inspect and fix the listed error locations.",
158	  ].join("\n");
159	}
