179	export const MAX_DIAGNOSTIC_MESSAGE = 500;
180	export const UNTRUSTED_FENCE_START = "(untrusted tool output";
181	export const UNTRUSTED_FENCE_END = "(end untrusted tool output)";
182	
183	/** Escapes and control characters removed, whitespace collapsed, fence markers defused, length capped. */
184	export function sanitizeDiagnosticMessage(message: unknown): string {
185	  const text = redactPlain(String(message ?? ""))
186	    .replace(/[\x00-\x1f\x7f-\x9f]+/g, " ")
187	    .replace(/\s+/g, " ")
188	    .trim()
189	    .split(UNTRUSTED_FENCE_START).join("(untrusted-tool-output")
190	    .split(UNTRUSTED_FENCE_END).join("(end-untrusted-tool-output)");
191	  return capText(text, MAX_DIAGNOSTIC_MESSAGE);
192	}
