194	const CONFIG_FILES = ["tsconfig.json", "Cargo.toml", "pyproject.toml", "go.mod", "package.json"];
195	
196	/** The nearest project config at or above the file, within the workspace, with its content hash. */
197	export function nearestConfig(workspace: string, file: string): DiagnosticConfig | undefined {
198	  const root = path.resolve(workspace);
199	  let dir = path.dirname(path.resolve(root, file));
200	  while (dir === root || dir.startsWith(root + path.sep)) {
201	    for (const name of CONFIG_FILES) {
202	      try {
203	        const full = path.join(dir, name);
204	        return { path: path.relative(root, full).split(path.sep).join("/"), sha256: crypto.createHash("sha256").update(fs.readFileSync(full)).digest("hex") };
205	      } catch {
206	        // Not here; try the next name, then the parent.
207	      }
208	    }
209	    if (dir === root) break;
210	    dir = path.dirname(dir);
211	  }
212	  return undefined;
213	}
214	
215	function cleanConfig(config: DiagnosticConfig | undefined): DiagnosticConfig | undefined {
216	  return config && { path: sanitizeDiagnosticMessage(config.path), sha256: config.sha256 };
217	}
