219	export function lspDiagnosticRecords(
220	  workspace: string,
221	  file: string,
222	  diagnostics: LspDiagnostic[],
223	  toolVersion?: string,
224	): StructuredDiagnostic[] {
225	  const config = cleanConfig(nearestConfig(workspace, file));
226	  return diagnostics.map((d) => ({
227	    tool: d.source ? `lsp:${sanitizeDiagnosticMessage(d.source)}` : "lsp",
228	    ...(toolVersion ? { toolVersion } : {}),
229	    ...(d.code !== undefined && d.code !== null ? { code: sanitizeDiagnosticMessage(d.code) } : {}),
230	    severity: d.severity,
231	    file: sanitizeDiagnosticMessage(file),
232	    line: d.range.start.line + 1,
233	    column: d.range.start.character + 1,
234	    message: sanitizeDiagnosticMessage(d.message),
235	    ...(config ? { config } : {}),
236	  }));
237	}
