239	/** Compiler output parsed by extractCompilerDiagnostics, as the same record type. */
240	export function compilerDiagnosticRecords(diagnostics: Diagnostic[], workspace?: string): StructuredDiagnostic[] {
241	  return diagnostics.map((d) => {
242	    const config = workspace ? cleanConfig(nearestConfig(workspace, d.file)) : undefined;
243	    return {
244	      tool: d.code?.startsWith("TS") ? "tsc" : /^E\d+$/.test(d.code ?? "") || d.file.endsWith(".rs") ? "cargo" : d.file.endsWith(".py") ? "pytest" : "compiler",
245	      ...(d.code ? { code: d.code } : {}),
246	      severity: d.severity,
247	      file: sanitizeDiagnosticMessage(d.file),
248	      ...(d.line !== undefined ? { line: d.line } : {}),
249	      ...(d.column !== undefined ? { column: d.column } : {}),
250	      message: sanitizeDiagnosticMessage(d.message),
251	      ...(config ? { config } : {}),
252	    };
253	  });
254	}
