59	   * The fake's log, read after the barrier: a query answered without a round trip (a cached list, a refusal, a timeout)
60	   * leaves the notifications it sent (didOpen, didChange, didClose) unlogged for a moment, so every reader waits for them.
61	   */
62	  log: () => Promise<Entry[]>;
63	  received: (method: string) => Promise<Entry[]>;
64	  /**
65	   * Waits until the server has received `method` for the file `name`, and until everything it sent in response has
66	   * reached the client. Use it after starting a query WITHOUT awaiting it: the query reads the file system before it
67	   * writes anything, so a bare `sync()` can overtake its notifications (seen as a flake under load).
68	   */
69	  seen: (method: string, name: string) => Promise<void>;
70	  /**
71	   * The log as it is on disk now, without the barrier. Only for a server that cannot answer it (never initialised,
72	   * deliberately unresponsive, already stopped), or inside a polling check.
73	   */
74	  rawLog: () => Entry[];
75	  /** The scenario the fake reads at its start: `node fake_lsp_scripted.mjs <scenarioFile>`. */
76	  scenarioFile: string;
77	  /** Sets the turn's abort signal on the bridge, as the agent does for the tool calls of a turn. */
78	  turnSignal: (signal: AbortSignal | undefined) => void;
79	  /** Shuts everything down, asserts every process the fake logged (server, grandchild) is gone, removes the temp tree. */
80	  close: () => Promise<void>;
81	}
82	
83	/**
84	 * `timings`: the manager's overrides of the product's timings. By default only the cold-start allowance is set, to 0: the
85	 * fake is ready the moment it has answered `initialize`, so an empty hover is "nothing here" at once and no test waits
86	 * out a warm-up it is not about. "product": no override at all (the product's values, seconds long).
87	 */
88	export function open(
89	  scenario: Record<string, unknown>,
90	  files: Record<string, string>,
91	  opts: { awaitProgress?: boolean; cmd?: string; args?: string[]; viaSymlink?: boolean; wsName?: string; timings?: Partial<LspTimings> | "product"; gate?: () => string | null } = {},
92	): Opened {
93	  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "nexus-lsp-char-")));
94	  const real = path.join(root, opts.wsName ?? "ws");
95	  fs.mkdirSync(real);
96	  for (const [name, text] of Object.entries(files)) {
97	    fs.mkdirSync(path.dirname(path.join(real, name)), { recursive: true });
98	    fs.writeFileSync(path.join(real, name), text);
99	  }
100	  let ws = real;
101	  if (opts.viaSymlink) {
102	    ws = path.join(root, "link");
103	    fs.symlinkSync(real, ws);
104	  }
105	  const logFile = path.join(root, "fake.log.jsonl");
106	  const scenarioFile = path.join(root, "scenario.json");
107	  fs.writeFileSync(scenarioFile, JSON.stringify({ ...scenario, log: logFile }));
108	  const mgr = new LspBridgeManager(ws, {
109	    servers: { ".ts": { cmd: opts.cmd ?? process.execPath, args: opts.args ?? (opts.cmd ? [] : [FAKE, scenarioFile]), languageId: "typescript", awaitProgress: opts.awaitProgress === true } },
110	    ...(opts.timings === "product" ? {} : { timings: opts.timings ?? { coldStartMs: 0 } }),
111	    ...(opts.gate ? { gate: opts.gate } : {}),
112	  });
113	  const bridge = new RustCoreBridge(ws);
114	  (bridge as any).lsp = mgr;
115	  const rawLog = (): Entry[] => (fs.existsSync(logFile) ? fs.readFileSync(logFile, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l)) : []);
116	  const client = async () => {
117	    const c = await mgr.getClientForFile("a.ts");
118	    assert.ok(c, "the fake server started");
119	    return c;
120	  };
121	  const sync = async () => {
122	    const running = [...((mgr as any).clients as Map<string, LspClient>).values()].filter((c) => c.initialized);
123	    for (const c of running) await c.sendRequest("test/sync", {}).catch(() => {}); // a server that just died has nothing more to log
124	  };
125	  const log = async () => {
126	    await sync();
127	    return rawLog();
128	  };
129	  return {
130	    root,
131	    ws,
132	    mgr,
133	    uri: (name) => pathToFileURL(path.join(ws, name)).href,
134	    tool: (name, args) => bridge.executeTool(name, args),
135	    client,
136	    sync,
137	    log,
138	    received: async (method) => (await log()).filter((e) => e.event === "recv" && e.method === method),
139	    seen: async (method, name) => {
140	      for (const end = performance.now() + 10_000; ; await sleep(10)) {
141	        if ((await log()).some((e) => e.event === "recv" && e.method === method && String(e.params?.textDocument?.uri ?? "").endsWith(`/${name}`))) break;
142	        assert.ok(performance.now() < end, `the server never received ${method} for ${name}`);
143	      }
144	      // The server answered that message before this round trip's reply, so the client has what it sent.
145	      await (await client()).sendRequest("test/sync", {});
146	    },
147	    rawLog,
148	    scenarioFile,
149	    turnSignal: (signal) => bridge.setTurnSignal(signal),
150	    close: async () => {
151	      bridge.shutdown();
152	      mgr.shutdownAll();
153	      const pids = rawLog().filter((e) => e.event === "start" || e.event === "grandchild").map((e) => e.pid!);
154	      const gone = await eventually(() => pids.every((pid) => !alive(pid)));
155	      fs.rmSync(root, { recursive: true, force: true });
156	      assert.ok(gone, `a process started for this test is still running: ${pids.filter(alive).join(", ")}`);
157	    },
158	  };
159	}
