161	/** The records inside a fenced lsp_diagnostics result. */
162	export function records(output: string): Array<Record<string, unknown>> {
163	  const lines = output.split("\n");
164	  assert.match(lines[0], /^\(untrusted tool output: lsp diagnostics for /);
165	  assert.equal(lines.at(-1), "(end untrusted tool output)");
166	  return JSON.parse(lines.slice(1, -1).join("\n"));
167	}
168	
169	const COUNTED = ["realpathSync", "statSync", "lstatSync", "openSync", "fstatSync", "readFileSync", "readSync", "closeSync", "existsSync", "accessSync", "readdirSync", "readlinkSync"] as const;
170	
171	/**
172	 * Runs `run` with the synchronous file-system functions a language-server client could use wrapped, and returns each call
173	 * made meanwhile as [function, first argument]. It counts calls to `node:fs` (one `realpathSync` is one call, although it
174	 * examines every component of the path), from any code in this process: wrap only the product call being measured.
175	 */
176	export async function countingFs<T>(run: () => Promise<T>): Promise<{ result: T; calls: Array<[string, string]> }> {
177	  const calls: Array<[string, string]> = [];
178	  const target = fsModule as unknown as Record<string, any>;
179	  const saved = COUNTED.map((name) => [name, target[name]] as const);
180	  for (const [name, original] of saved) {
181	    target[name] = Object.assign(function (this: unknown, ...args: unknown[]) {
182	      calls.push([name, String(args[0])]);
183	      return original.apply(this, args);
184	    }, original);
185	  }
186	  syncBuiltinESMExports();
187	  try {
188	    return { result: await run(), calls };
189	  } finally {
190	    for (const [name, original] of saved) target[name] = original;
191	    syncBuiltinESMExports();
192	  }
193	}
