1	// Scripted stdio language server for characterisation tests. Usage: node fake_lsp_scripted.mjs <scenario.json>
2	// It does nothing by itself except answer `initialize`, `shutdown`/`exit` and every other request with `null`;
3	// everything else is driven by the scenario. The existing fake_lsp_server.mjs is separate and unchanged.
4	//
5	// Scenario (JSON object; every key but `log` is optional):
6	//   log              path of a JSON-lines file; one entry per event, appended synchronously, in order:
7	//                      {event:"start", pid}                      this process
8	//                      {event:"grandchild", pid}                 the process started by `spawnGrandchild`
9	//                      {event:"recv", method, id?, params, docs} every request and notification received; `docs` is the
10	//                                                                text this server holds per URI AFTER applying the message
11	//                                                                (didOpen / didChange full text / didClose)
12	//                      {event:"reply", to, id, result?, error?}  the client's answer to a server request (`to` = its method)
13	//                      {event:"answer", to, result?, error?}     this server's answer to `textDocument/diagnostic`
14	//                      {event:"signal", signal}                  a signal caught because of `ignoreSigterm`
15	//                    A `text` longer than 2000 characters is logged as {elidedChars: n}.
16	//   stderrOnStart    text written to stderr at start
17	//   exitOnStart      exit code: exit at once (after stderrOnStart), before reading anything
18	//   spawnGrandchild  true: start a child process that idles (it ends by itself after 60 s) and log its pid
19	//   ignoreSigterm    true: catch SIGTERM and keep running
20	//   ignoreShutdown   true: never answer `shutdown`, ignore `exit`
21	//   initialize       "never" (no answer), or the result object (default {capabilities: {}})
22	//   hover            "fromText": answer from the held text with contents = JSON {word, docs} where `word` is the
23	//                    identifier at the position (character read as a UTF-16 offset) and `docs` maps basename -> held text;
24	//                    or {"<basename>" | "*": <result>}: a scripted result per file (null = no hover, "never" = no reply)
25	//   definition       "fromText": the Location of the first `def <word>` in any held document, else null;
26	//                    or {"<basename>" | "*": <result>} ("never" = no reply)
27	//   loadedOn         a method ("test/release"): until it is received, hover and definition answer null, as a server
28	//                    that has not loaded the project yet does
29	//   diagnostic       how `textDocument/diagnostic` is answered (announce `diagnosticProvider` through `initialize`):
30	//                    "fromText": a full report with one item whose message names the file and the text held for every
31	//                    document (so a file's report depends on the others), with that message as resultId; or
32	//                    {kind: "unchanged"} when the request's previousResultId equals it;
33	//                    or a list of answers used in order, the last one repeating: {result}, {error} or "never"
34	//   on               {"<trigger>": [action, ...]} where trigger is a received method ("initialized", "test/release"), or
35	//                    "<method>#<basename>" for one file ("textDocument/didOpen#a.ts"). Actions run before the reply.
36	//   action           {after?: ms, request?: true, method, params}: send a notification, or with `request` a server
37	//                    request whose reply is logged. Without `after` it is sent synchronously, in order.
38	// In action params and scripted results a string is replaced when it is exactly "$uri" (the triggering document's URI),
39	// "$realuri" (the same file with symlinks resolved), "$uri:lowerhex" (the same URI with lower-case percent escapes),
40	// "$uri:unicode" (the same URI with its non-ASCII characters not percent-encoded), "$version" (its version, as a number),
41	// "$text" (the text this server holds for it; "" once closed), or starts with "$root/" (the client's rootUri; also in object keys).
42	// The server exits when its stdin ends, so it cannot outlive a test process that died.
43	import fs from "node:fs";
44	import path from "node:path";
45	import { spawn } from "node:child_process";
46	import { fileURLToPath, pathToFileURL } from "node:url";
47	
48	const S = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
49	const elide = (_k, v) => (_k === "text" && typeof v === "string" && v.length > 2000 ? { elidedChars: v.length } : v);
50	const log = (entry) => fs.appendFileSync(S.log, `${JSON.stringify(entry, elide)}\n`);
51	const docs = new Map(); // uri -> text
52	const sent = new Map(); // server request id -> method
53	let loaded = !S.loadedOn;
54	let rootUri = "";
55	let nextId = 1;
56	let buf = Buffer.alloc(0);
57	
58	log({ event: "start", pid: process.pid });
59	if (S.stderrOnStart) fs.writeSync(2, S.stderrOnStart);
60	if (S.spawnGrandchild) {
61	  const child = spawn(process.execPath, ["-e", "setTimeout(() => {}, 60000)"], { stdio: "ignore" });
62	  child.unref();
63	  log({ event: "grandchild", pid: child.pid });
64	}
65	if (S.ignoreSigterm) process.on("SIGTERM", () => log({ event: "signal", signal: "SIGTERM" }));
66	if (typeof S.exitOnStart === "number") process.exit(S.exitOnStart);
67	
68	function send(msg) {
69	  const body = JSON.stringify({ jsonrpc: "2.0", ...msg });
70	  process.stdout.write(`Content-Length: ${Buffer.byteLength(body)}\r\n\r\n${body}`);
71	}
72	
73	function fill(value, ctx) {
74	  if (typeof value === "string") {
75	    if (value === "$uri") return ctx.uri;
76	    if (value === "$realuri") return pathToFileURL(fs.realpathSync(fileURLToPath(ctx.uri))).href;
77	    if (value === "$uri:lowerhex") return ctx.uri.replace(/%[0-9A-F]{2}/g, (escape) => escape.toLowerCase());
78	    if (value === "$uri:unicode") return ctx.uri.replace(/(?:%[89A-F][0-9A-F])+/g, (escapes) => decodeURIComponent(escapes));
79	    if (value === "$version") return ctx.version;
80	    if (value === "$text") return docs.get(ctx.uri) ?? "";
81	    return value.startsWith("$root/") ? rootUri + value.slice(5) : value;
82	  }
83	  if (Array.isArray(value)) return value.map((v) => fill(v, ctx));
84	  if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([k, v]) => [k.startsWith("$root/") ? rootUri + k.slice(5) : k, fill(v, ctx)]));
85	  return value;
86	}
87	
88	function act(action, ctx) {
89	  const msg = { method: action.method, params: fill(action.params, ctx) };
90	  if (action.request) {
91	    msg.id = `s${nextId++}`;
92	    sent.set(msg.id, action.method);
93	  }
94	  send(msg);
95	}
96	
97	function run(trigger, ctx) {
98	  for (const action of S.on?.[trigger] ?? []) {
99	    if (action.after) setTimeout(() => act(action, ctx), action.after);
100	    else act(action, ctx);
101	  }
102	}
103	
104	const base = (uri) => path.basename(fileURLToPath(uri));
105	
106	function wordAt(uri, position) {
107	  const line = (docs.get(uri) ?? "").split("\n")[position?.line] ?? "";
108	  const isWord = (i) => /[A-Za-z0-9_]/.test(line[i] ?? "");
109	  let start = position?.character;
110	  if (!isWord(start)) return "";
111	  let end = start;
112	  while (isWord(start - 1)) start--;
113	  while (isWord(end + 1)) end++;
114	  return line.slice(start, end + 1);
115	}
116	
117	function answer(script, m, fromText) {
118	  const uri = m.params.textDocument.uri;
119	  if (!loaded) return null;
120	  if (script === "fromText") return fromText(uri, wordAt(uri, m.params.position));
121	  const scripted = script?.[base(uri)] ?? script?.["*"] ?? null;
122	  return fill(scripted, { uri });
123	}
124	
125	function hoverFromText(_uri, word) {
126	  return { contents: JSON.stringify({ word, docs: Object.fromEntries([...docs].map(([u, text]) => [base(u), text])) }) };
127	}
128	
129	function definitionFromText(_uri, word) {
130	  for (const [uri, text] of docs) {
131	    const lines = text.split("\n");
132	    const line = lines.findIndex((l) => word !== "" && l.includes(`def ${word}`));
133	    if (line < 0) continue;
134	    const character = lines[line].indexOf(`def ${word}`) + 4;
135	    return { uri, range: { start: { line, character }, end: { line, character: character + word.length } } };
136	  }
137	  return null;
138	}
139	
140	let pulls = 0;
141	function diagnosticAnswer(m) {
142	  const uri = m.params.textDocument.uri;
143	  if (S.diagnostic !== "fromText") return S.diagnostic?.[Math.min(pulls++, S.diagnostic.length - 1)] ?? { result: null };
144	  const message = `${base(uri)} with ${[...docs].map(([u, text]) => `${base(u)}=${text}`).sort().join(" ")}`;
145	  if (m.params.previousResultId === message) return { result: { kind: "unchanged", resultId: message } };
146	  const range = { start: { line: 0, character: 0 }, end: { line: 0, character: 1 } };
147	  return { result: { kind: "full", resultId: message, items: [{ range, severity: 1, message, source: "fake" }] } };
148	}
149	
150	function handle(m) {
151	  if (m.method === undefined) {
152	    log({ event: "reply", to: sent.get(m.id), id: m.id, ...("result" in m ? { result: m.result } : {}), ...(m.error ? { error: m.error } : {}) });
153	    return;
154	  }
155	  const doc = m.params?.textDocument;
156	  if (m.method === "initialize") rootUri = m.params.rootUri;
157	  if (m.method === S.loadedOn) loaded = true;
158	  if (m.method === "textDocument/didOpen") docs.set(doc.uri, doc.text);
159	  if (m.method === "textDocument/didChange") docs.set(doc.uri, m.params.contentChanges.at(-1).text);
160	  if (m.method === "textDocument/didClose") docs.delete(doc.uri);
161	  log({ event: "recv", method: m.method, ...(m.id !== undefined ? { id: m.id } : {}), params: m.params, docs: Object.fromEntries([...docs].map(([u, text]) => [u, elide("text", text)])) });
162	
163	  const ctx = { uri: doc?.uri, version: doc?.version };
164	  run(m.method, ctx);
165	  if (doc?.uri) run(`${m.method}#${base(doc.uri)}`, ctx);
166	
167	  if (m.method === "exit") {
168	    if (!S.ignoreShutdown) process.exit(0);
169	    return;
170	  }
171	  if (m.id === undefined) return;
172	  if (m.method === "initialize") {
173	    if (S.initialize !== "never") send({ id: m.id, result: S.initialize ?? { capabilities: {} } });
174	  } else if (m.method === "shutdown") {
175	    if (!S.ignoreShutdown) send({ id: m.id, result: null });
176	  } else if (m.method === "textDocument/hover" || m.method === "textDocument/definition") {
177	    const result = m.method === "textDocument/hover" ? answer(S.hover, m, hoverFromText) : answer(S.definition, m, definitionFromText);
178	    if (result !== "never") send({ id: m.id, result });
179	  }
180	  else if (m.method === "textDocument/diagnostic") {
181	    const scripted = diagnosticAnswer(m);
182	    if (scripted === "never") return;
183	    const reply = scripted.error ? { error: scripted.error } : { result: fill(scripted.result, ctx) };
184	    log({ event: "answer", to: m.method, ...reply });
185	    send({ id: m.id, ...reply });
186	  }
187	  else send({ id: m.id, result: null });
188	}
189	
190	process.stdin.on("end", () => process.exit(0));
191	process.stdin.on("data", (chunk) => {
192	  buf = Buffer.concat([buf, chunk]);
193	  for (;;) {
194	    const headerEnd = buf.indexOf("\r\n\r\n");
195	    if (headerEnd < 0) return;
196	    const length = Number(/Content-Length:\s*(\d+)/i.exec(buf.subarray(0, headerEnd).toString())[1]);
197	    if (buf.length < headerEnd + 4 + length) return;
198	    const body = buf.subarray(headerEnd + 4, headerEnd + 4 + length).toString();
199	    buf = buf.subarray(headerEnd + 4 + length);
200	    handle(JSON.parse(body));
201	  }
202	});
