140	test("FIXED (defect 10): a missing server binary fails at once as 'not installed', naming the command, on the first call and on the next (product timings: nothing is waited for)", async () => {
141	  const missing = path.join(os.tmpdir(), "nexus-lsp-char-no-such-dir", "no-such-language-server");
142	  const s = open({}, { "a.ts": "x\n" }, { cmd: missing, timings: "product" });
143	  const notInstalled = `Language server not installed: ${missing} was not found.`;
144	  try {
145	    let started = performance.now();
146	    const first = await s.tool("lsp_diagnostics", { path: "a.ts" });
147	    const firstMs = performance.now() - started;
148	    assert.deepEqual(first, { success: false, output: "", error: unavailable(notInstalled) });
149	    started = performance.now();
150	    const second = await s.tool("lsp_hover", { path: "a.ts", line: 1, character: 1 });
151	    const secondMs = performance.now() - started;
152	    assert.deepEqual(second, { success: false, output: "No hover info", error: notInstalled });
153	    // The product's start timeout is 10 s: neither call came near it. (That the second call does not even look again is in lsp_readiness.test.ts.)
154	    assert.ok(firstMs < 1000 && secondMs < 1000, `first ${Math.round(firstMs)} ms, second ${Math.round(secondMs)} ms`);
155	    const status = s.mgr.serverStatus("a.ts")!;
156	    assert.deepEqual([status.state, status.cause?.kind, status.detail], ["failed", "not_installed", notInstalled]);
157	    assert.deepEqual(s.rawLog(), [], "nothing was started"); // raw: there is no server
158	  } finally {
159	    await s.close();
160	  }
161	});
