    // The process handle and its three pipes are closed by the event loop, a turn after the exit was seen.
    assert.ok(await eventually(() => resources(["Timeout", "ProcessWrap", "PipeWrap"]).join() === before.join(), 2000), `handles left: ${resources(["Timeout", "ProcessWrap", "PipeWrap"])} (before: ${before})`);
