    assert.deepEqual(stops(s), ["shutdown", "exit"]);
    assert.ok(elapsed < 900, `no grace was waited out (the shortest is 1 s): ${Math.round(elapsed)} ms`);
    assert.equal(s.mgr.serverStatus("a.ts")!.state, "stopped");
  } finally {
    await s.close();
  }
});

